package config

import (
	"errors"
	"fmt"
	"os"
	"time"

	"github.com/PMPRR/SCOM---Trabalho-2/internal/ingest"
)

type Config struct {
	Env         string
	Addr        string
	DatabaseURL string

	// IngestInterval is how often the server collects readings from the
	// external sources. Zero turns the collection off.
	IngestInterval time.Duration
	// CEMADEN is enabled by an e-mail and password (the token is then
	// renewed automatically) or by a token generated by hand, which lasts
	// about four hours.
	CemadenEmail    string
	CemadenPassword string
	CemadenToken    string
}

func Load() (Config, error) {
	cfg := Config{
		Env:         getenv("APP_ENV", "dev"),
		Addr:        getenv("APP_ADDR", ":8080"),
		DatabaseURL: getenv("DATABASE_URL", ""),

		CemadenEmail:    getenv("CEMADEN_EMAIL", ""),
		CemadenPassword: getenv("CEMADEN_PASSWORD", ""),
		CemadenToken:    getenv("CEMADEN_TOKEN", ""),
	}
	if cfg.DatabaseURL == "" {
		return Config{}, errors.New("DATABASE_URL is required")
	}
	if (cfg.CemadenEmail == "") != (cfg.CemadenPassword == "") {
		return Config{}, errors.New("CEMADEN_EMAIL and CEMADEN_PASSWORD must be set together")
	}

	interval, err := time.ParseDuration(getenv("INGEST_INTERVAL", "0"))
	if err != nil || interval < 0 {
		return Config{}, fmt.Errorf("INGEST_INTERVAL must be a duration such as 1h or 30m (0 disables)")
	}
	// Public services ask not to be polled in a tight loop.
	if interval > 0 && interval < 10*time.Minute {
		return Config{}, errors.New("INGEST_INTERVAL must be at least 10m")
	}
	cfg.IngestInterval = interval

	return cfg, nil
}

// IngestCredentials groups the secrets of the external sources.
func (c Config) IngestCredentials() ingest.Credentials {
	return ingest.Credentials{
		CemadenEmail:    c.CemadenEmail,
		CemadenPassword: c.CemadenPassword,
		CemadenToken:    c.CemadenToken,
	}
}

// ---- Helper
func getenv(key, fallback string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return fallback
}
